const content = $input.first().json.choices[0].message.content;
let parsed = {};
try {
  parsed = JSON.parse(content);
} catch (e) {
  const m = content.match(/\{[\s\S]+\}/);
  if (m) parsed = JSON.parse(m[0]);
}
return [{
  json: {
    Blog_Tytul: parsed.blog_tytul || '',
    Blog_Meta_Description: parsed.blog_meta_description || '',
    Blog_Slug: parsed.blog_slug || ''
  }
}];

const pub = $('Get Publikacja').first().json;
const userCorrection = $('Execute Workflow Trigger').first().json.user_correction || '';
const pubId = $('Execute Workflow Trigger').first().json.publication_id;

let batchNum = 0;
try { const h = JSON.parse(pub.Blog_Grafika_Historia || '[]'); if (Array.isArray(h)) batchNum = h.length; } catch (e) {}

let prompty = [];
try { const raw = pub.Blog_Grafika_Prompty || '[]'; prompty = typeof raw === 'string' ? JSON.parse(raw) : raw; if (!Array.isArray(prompty)) prompty = []; } catch (e) { prompty = []; }

const FALLBACKS = [
  'High aerial drone shot of a whole coastal recreational plot and its boundaries near the Baltic Sea, meadow and pine woods, cool blue-hour dawn light, photorealistic photograph shot on Canon EOS R5, 35mm lens, f/8, no faces, no text overlays, no logo',
  'Eye-level view standing on a sandy access track toward a coastal recreational plot, meadow and pine trunks in the foreground, hard midday sunlight, contrasty shadows, photorealistic photograph shot on Canon EOS R5, 35mm lens, f/8, no faces, no text overlays, no logo',
  'Low-angle golden-hour close view of a coastal plot edge where meadow meets pine forest near the Baltic, dunes and a footpath, warm backlight, long shadows, photorealistic photograph shot on Canon EOS R5, 35mm lens, f/8, no faces, no text overlays, no logo'
];
for (let i = 0; i < 3; i++) { if (typeof prompty[i] !== 'string' || prompty[i].trim().length === 0) prompty[i] = FALLBACKS[i]; }

const VARIANTS = [
  'wide high aerial drone perspective, cool blue-hour dawn light',
  'eye-level ground perspective, hard midday sunlight, contrasty shadows',
  'low-angle golden-hour close view, warm backlight, long shadows',
  'elevated three-quarter angle, overcast soft diffused light',
  'ground-level wide shot, clear morning light, long side shadows',
  'top-down flat-lay drone angle, crisp afternoon light'
];
const correctionSuffix = userCorrection ? `. Modification: ${userCorrection}` : '';

return prompty.slice(0, 3).map((p, idx) => {
  const v = VARIANTS[(idx + batchNum * 3) % VARIANTS.length];
  return { json: { publication_id: pubId, prompt_index: idx + 1, prompt: `${p}. Alternative rendering: ${v}${correctionSuffix}` } };
});

const items = $input.all();
