const pubRaw = $('Get Publikacja').first().json;
const pub = pubRaw.fields ? pubRaw.fields : pubRaw;
const sectionNum = $('Execute Workflow Trigger').first().json.regen_section_num;
const newSectionContent = $input.first().json.choices[0].message.content.trim();
const pubId = $('Execute Workflow Trigger').first().json.publication_id;

const html = pub['Treść Bloga (HTML)'] || '';
const sections = [];

const firstH2 = html.search(/<h2/i);
if (firstH2 > 0) {
  sections.push({ start: 0, end: firstH2, content: html.substring(0, firstH2) });
}

const h2Regex = /<h2[^>]*>([\s\S]*?)<\/h2>([\s\S]*?)(?=<h2|<\/?(?:h1|main|article|body)|$)/gi;
let match;
while ((match = h2Regex.exec(html)) !== null) {
  sections.push({ start: match.index, end: match.index + match[0].length, content: match[0] });
}

if (sectionNum < 1 || sectionNum > sections.length) {
  throw new Error('Sekcja poza zakresem: ' + sectionNum + ' (sekcji: ' + sections.length + ')');
}

const sec = sections[sectionNum - 1];
const newHtml = html.substring(0, sec.start) + newSectionContent + html.substring(sec.end);

return [{
  json: {
    publication_id: pubId,
    new_html: newHtml
  }
}];

const resp = $input.item.json;
const scenario = JSON.parse(resp.choices[0].message.content);
const LOGO_URL = 'https://dl.dropboxusercontent.com/scl/fi/muheamff4x2b5ue9abxnh/download.jpg?rlkey=cfjuz3qovtu3b3spipfljsoum&dl=1';

if (Array.isArray(scenario.scenes) && scenario.scenes.length) {
  // 1) narracja (voice) BEZ hashtagów i linków (lektor by je czytał)
  scenario.scenes.forEach(sc => {
    if (Array.isArray(sc.elements)) {
      sc.elements.forEach(el => {
        if (el.type === 'voice' && typeof el.text === 'string') {
          el.text = el.text
            .replace(/#[\p{L}\d_]+/gu, '')
            .replace(/https?:\/\/\S+/g, '')
            .replace(/\s{2,}/g, ' ')
            .trim();
        }
      });
    }
  });
  // 2) OSTATNIA scena: obraz = REALNE logo (nie flux)
  const last = scenario.scenes[scenario.scenes.length - 1];
  if (Array.isArray(last.elements)) {
    last.elements = last.elements.map(el =>
      el.type === 'image'
        ? { type: 'image', src: LOGO_URL, resize: 'contain', position: 'center-center' }
        : el
    );
  }
}

resp.choices[0].message.content = JSON.stringify(scenario);
return { json: resp };
